<?php require 'common.php';admin_required();$rows=db()->query('SELECT v.*, (SELECT path FROM photos p WHERE p.vehicle_id=v.id ORDER BY position,id LIMIT 1) AS cover FROM vehicles v ORDER BY id DESC')->fetchAll();admin_top('Gerenciar veículos');?><p class="muted">Cadastre, edite, marque os destaques da página inicial ou remova veículos do estoque.</p><p><a href="edit.php" class="button red">+ ADICIONAR VEÍCULO</a></p><div class="userbox" style="overflow-x:auto"><table class="admin-table"><thead><tr><th>Foto</th><th>Veículo</th><th>Valor</th><th>Situação</th><th>Destaque</th><th>Ações</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><img src="../<?=h(photo_path($r['cover']))?>" alt=""></td><td><?=h($r['title'])?></td><td><?=h(money($r['price']))?></td><td><span class="pill"><?=h($r['status'])?></span></td><td><?=((int)$r['featured'])?'Sim':'Não'?></td><td><a class="link" href="edit.php?id=<?=$r['id']?>">Editar / Fotos</a> · <form style="display:inline" method="post" action="delete.php" onsubmit="return confirm('Excluir o veículo e todas as suas fotos?')"><?=token_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="button-sm danger">Excluir</button></form></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><p>Nenhum veículo cadastrado.</p><?php endif;?></div><?php admin_bottom(); ?>
